// kb_documentCursorValues 提取用于构造 nextCursor 的排序列值,顺序与有效排序一致。
//
// 参数:
//   - row: 查询结果中的一行模型。
//   - seq: 排序列及方向,顺序与游标值顺序一致。
//
// 返回值:
//   - []any: 与 seq 一一对应的列值切片。
func kb_documentCursorValues(row KbDocument, seq []dynq.SortField) []any {
	vals := make([]any, len(seq))
	for i, sf := range seq {
		switch sf.Key {
		case "id":
			vals[i] = row.ID
		case "title":
			vals[i] = row.Title
		case "status":
			vals[i] = row.Status
		case "validFrom":
			vals[i] = row.ValidFrom
		case "validTo":
			vals[i] = row.ValidTo
		case "indexedAt":
			vals[i] = row.IndexedAt
		case "createdAt":
			vals[i] = row.CreatedAt
		case "updatedAt":
			vals[i] = row.UpdatedAt
		default:
			vals[i] = nil
		}
	}
	return vals
}

// ListKbDocument 按 params 的过滤、排序、投影与分页条件查询列表页。
// 返回本页行、是否还有下一页与续翻游标;total 由 CountKbDocument 单独计算
// (非强一致快照)。生成代码为纯函数,不持有连接状态。
// 未查询列在结果中留零值(动态投影固有语义),需区分时按请求 fields 做 DTO 化。
//
// 参数:
//   - ctx:    查询上下文。
//   - db:     数据库连接,满足 DBTX 接口即可。
//   - params: typed 查询参数,可由 ParseKbDocumentQuery 产出或直接构造。
//   - opts:   运行期能力收窄选项;禁用目标不在 registry 时返回错误。
//
// 返回值:
//   - dynq.Result[KbDocument]: 本页行、是否还有下一页与续翻游标。
//   - error:              查询或校验失败时的错误。
func ListKbDocument(ctx context.Context, db DBTX, params ListKbDocumentParams, opts ...dynq.QueryOption) (dynq.Result[KbDocument], error) {
	cfg, err := dynq.NewQueryConfig(kb_documentRegistry, opts...)
	if err != nil {
		return dynq.Result[KbDocument]{}, err
	}
	if err := validateKbDocumentParams(params, cfg); err != nil {
		return dynq.Result[KbDocument]{}, err
	}
	limit, err := dynq.CheckPagination(kb_documentRegistry, params.Limit, params.Offset, params.After)
	if err != nil {
		return dynq.Result[KbDocument]{}, err
	}
	// 解析有效排序:未指定排序时回落表级 @default_sort。
	seq, err := dynq.ResolveSort(kb_documentRegistry, cfg, params.OrderBy)
	if err != nil {
		return dynq.Result[KbDocument]{}, err
	}
	fp := dynq.CursorFingerprint(kb_documentRegistry.Resource, seq)
	// 计算 SELECT 列:投影列并集排序列(排序所需列始终参与查询)。
	cols := dynq.SelectColumns(kb_documentRegistry, params.SelectFields, seq)
	b := sq.Select(cols...).From("kb_document").PlaceholderFormat(sq.Dollar).Where(sq.And(buildKbDocumentWhere(params))).
		OrderBy(dynq.OrderBySQL(seq)).Limit(uint64(limit) + 1)
	// After 非 nil 时为游标模式:解码并校验游标,从该位置继续读取。
	if params.After != nil {
		vals, err := dynq.DecodeCursor(*params.After, fp, seq)
		if err != nil {
			return dynq.Result[KbDocument]{}, err
		}
		seek, err := dynq.SeekPredicate(seq, vals)
		if err != nil {
			return dynq.Result[KbDocument]{}, err
		}
		b = b.Where(seek)
	}
	if params.Offset > 0 {
		b = b.Offset(uint64(params.Offset))
	}
	query, args, err := b.ToSql()
	if err != nil {
		return dynq.Result[KbDocument]{}, err
	}
	rows, err := db.Query(ctx, query, args...)
	if err != nil {
		return dynq.Result[KbDocument]{}, err
	}
	items, err := pgx.CollectRows(rows, pgx.RowToStructByNameLax[KbDocument])
	if err != nil {
		return dynq.Result[KbDocument]{}, err
	}
	// 以 LIMIT n+1 探测是否还有下一页,并构造 nextCursor。
	hasMore := len(items) > int(limit)
	if hasMore {
		items = items[:limit]
	}
	var next string
	if hasMore {
		next, err = dynq.EncodeCursor(fp, seq, kb_documentCursorValues(items[len(items)-1], seq))
		if err != nil {
			return dynq.Result[KbDocument]{}, err
		}
	}
	return dynq.Result[KbDocument]{Items: items, HasMore: hasMore, NextCursor: next}, nil
}

// CountKbDocument 统计满足过滤条件的行数,与分页模式和游标位置无关;
// 忽略投影、排序与游标。
//
// 参数:
//   - ctx:    查询上下文。
//   - db:     数据库连接,满足 DBTX 接口即可。
//   - params: typed 查询参数,与 ListKbDocument 使用同一份形态复核。
//   - opts:   运行期能力收窄选项。
//
// 返回值:
//   - int64: 满足过滤条件的行数。
//   - error: 查询或校验失败时返回错误。
func CountKbDocument(ctx context.Context, db DBTX, params ListKbDocumentParams, opts ...dynq.QueryOption) (int64, error) {
	cfg, err := dynq.NewQueryConfig(kb_documentRegistry, opts...)
	if err != nil {
		return 0, err
	}
	if err := validateKbDocumentParams(params, cfg); err != nil {
		return 0, err
	}
	if _, err := dynq.CheckPagination(kb_documentRegistry, params.Limit, params.Offset, params.After); err != nil {
		return 0, err
	}
	query, args, err := sq.Select("COUNT(*)").From("kb_document").PlaceholderFormat(sq.Dollar).Where(sq.And(buildKbDocumentWhere(params))).ToSql()
	if err != nil {
		return 0, err
	}
	var total int64
	if err := db.QueryRow(ctx, query, args...).Scan(&total); err != nil {
		return 0, err
	}
	return total, nil
}

